//! Explicit hardware check. Plays only the original quiet fixtures generated by scripts/.
use audio_engine::{AudioEngine, AudioSnapshot};
use player_domain::PlaybackState;
use std::{
    path::PathBuf,
    thread,
    time::{Duration, Instant},
};

fn wait(
    engine: &AudioEngine,
    label: &str,
    condition: impl Fn(&AudioSnapshot) -> bool,
) -> AudioSnapshot {
    let deadline = Instant::now() + Duration::from_secs(8);
    loop {
        let state = engine.snapshot();
        assert!(state.error.is_none(), "{label}: {state:?}");
        if condition(&state) {
            return state;
        }
        assert!(Instant::now() < deadline, "Timed out: {label}: {state:?}");
        thread::sleep(Duration::from_millis(10));
    }
}

fn measure_track_changes(engine: &AudioEngine, root: &std::path::Path) {
    let mut timings = Vec::with_capacity(9);
    for name in [
        "Auvra Quiet Check.wav",
        "Auvra Quiet Check.flac",
        "Auvra Mono Check.wav",
    ]
    .into_iter()
    .cycle()
    .take(9)
    {
        let path = root.join(name);
        let before = engine.snapshot();
        let started = Instant::now();
        engine.load(path);
        loop {
            let current = engine.snapshot();
            assert!(current.error.is_none(), "Track change: {current:?}");
            if current.generation > before.generation && current.position_ms > 0 {
                timings.push(started.elapsed().as_secs_f64() * 1000.0);
                break;
            }
            assert!(
                started.elapsed() < Duration::from_secs(5),
                "Track change stalled"
            );
            thread::sleep(Duration::from_millis(1));
        }
    }
    timings.sort_by(f64::total_cmp);
    println!(
        "Local load to first measured PCM: median {:.1} ms, range {:.1}–{:.1} ms over {} WAV/FLAC/mono switches",
        timings[timings.len() / 2],
        timings[0],
        timings[timings.len() - 1],
        timings.len()
    );
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let root = PathBuf::from(std::env::args().nth(1).expect("fixture directory"));
    let engine = AudioEngine::new()?;
    engine.set_volume(0.3)?;
    assert!(engine.set_volume(f32::NAN).is_err());
    engine.load(root.join("Auvra Quiet Check.wav"));
    let wav = wait(&engine, "WAV output", |s| {
        s.state == PlaybackState::Playing && s.position_ms > 200
    });
    assert_eq!(wav.info.as_ref().unwrap().duration_ms, 8000);
    assert!(wav.statistics.callbacks > 0 && wav.statistics.nonzero_frames > 0);
    println!(
        "WAV: device={:?}, rate={}, source=44100/stereo, position={}ms, {:?}",
        wav.device_name, wav.output_rate, wav.position_ms, wav.statistics
    );
    engine.pause();
    thread::sleep(Duration::from_millis(80));
    let paused = engine.snapshot();
    thread::sleep(Duration::from_millis(200));
    assert_eq!(engine.snapshot().position_ms, paused.position_ms);
    assert_eq!(
        engine.snapshot().statistics.media_frames,
        paused.statistics.media_frames
    );
    engine.seek(4000);
    wait(&engine, "paused seek", |s| {
        s.state == PlaybackState::Paused && s.position_ms == 4000
    });
    engine.resume();
    wait(&engine, "resume", |s| {
        s.state == PlaybackState::Playing && s.position_ms > 4100
    });
    engine.seek(1200);
    engine.seek(2000);
    engine.seek(6500);
    wait(&engine, "coalesced seek", |s| {
        s.state == PlaybackState::Playing && (6500..7000).contains(&s.position_ms)
    });
    engine.stop();
    assert_eq!(engine.snapshot().state, PlaybackState::Stopped);
    assert_eq!(engine.snapshot().position_ms, 0);
    thread::sleep(Duration::from_millis(100));
    engine.seek(3000);
    wait(&engine, "seek after stop", |s| {
        s.state == PlaybackState::Paused && s.position_ms == 3000
    });
    engine.resume();
    wait(&engine, "resume after stop", |s| {
        s.state == PlaybackState::Playing && s.position_ms > 3100
    });
    engine.load(root.join("Auvra Quiet Check.flac"));
    let flac = wait(&engine, "FLAC output", |s| {
        s.state == PlaybackState::Playing && s.position_ms > 100
    });
    assert_eq!(flac.info.as_ref().unwrap().duration_ms, 8000);
    engine.pause();
    engine.seek(8000);
    wait(&engine, "paused EOF", |s| {
        s.state == PlaybackState::Paused && s.position_ms == 8000
    });
    engine.resume();
    wait(&engine, "resume at EOF", |s| {
        s.state == PlaybackState::Stopped && s.position_ms == 8000
    });
    engine.seek(7700);
    engine.resume();
    let eof = wait(&engine, "natural FLAC EOF", |s| {
        s.state == PlaybackState::Stopped && s.position_ms == 8000
    });
    println!(
        "FLAC: sample-accurate seek, pause/resume, coalescing, stop/reopen, EOF passed; {:?}",
        eof.statistics
    );
    engine.load(root.join("Auvra Mono Check.wav"));
    wait(&engine, "mono resampling", |s| {
        s.state == PlaybackState::Playing
            && s.position_ms > 100
            && s.info
                .as_ref()
                .is_some_and(|i| i.channels == 1 && i.sample_rate == 22050)
    });
    engine.set_volume(0.0)?;
    thread::sleep(Duration::from_millis(80));
    let muted = engine.snapshot();
    thread::sleep(Duration::from_millis(100));
    let later = engine.snapshot();
    assert_eq!(
        muted.statistics.nonzero_frames,
        later.statistics.nonzero_frames
    );
    assert!(later.statistics.media_frames > muted.statistics.media_frames);
    engine.load(root.join("does-not-exist.wav"));
    let deadline = Instant::now() + Duration::from_secs(3);
    while engine.snapshot().error.is_none() {
        assert!(Instant::now() < deadline);
        thread::sleep(Duration::from_millis(10));
    }
    assert_eq!(
        engine.snapshot().error.unwrap().code,
        player_domain::ErrorCode::FileMissing
    );
    engine.set_volume(0.3)?;
    engine.load(root.join("Auvra Quiet Check.flac"));
    wait(&engine, "recovery", |s| {
        s.state == PlaybackState::Playing && s.position_ms > 100
    });
    let final_state = engine.snapshot();
    engine.stop();
    drop(engine);
    println!(
        "Mono 22050 → device rate, gain/mute, missing-file recovery and stream shutdown passed; final {:?}",
        final_state.statistics
    );
    let cold = AudioEngine::new()?;
    cold.set_volume(0.3)?;
    cold.load_at(root.join("Auvra Quiet Check.wav"), 4000, false);
    wait(&cold, "atomic paused restore", |s| {
        s.state == PlaybackState::Paused && s.position_ms == 4000
    });
    thread::sleep(Duration::from_millis(200));
    assert_eq!(cold.snapshot().position_ms, 4000);
    assert_eq!(cold.snapshot().statistics.media_frames, 0);
    assert_eq!(cold.snapshot().statistics.nonzero_frames, 0);
    cold.resume();
    wait(&cold, "resume restored position", |s| {
        s.state == PlaybackState::Playing && s.position_ms > 4100
    });
    cold.load_at(root.join("Auvra Quiet Check.flac"), 2000, false);
    wait(&cold, "paused track transition", |s| {
        s.state == PlaybackState::Paused && s.position_ms == 2000
    });
    thread::sleep(Duration::from_millis(200));
    assert_eq!(cold.snapshot().position_ms, 2000);
    println!(
        "M4 atomic load: cold paused preparation submitted 0 media/nonzero frames; resume started at 4 s; paused transition held 2 s"
    );
    measure_track_changes(&cold, &root);
    Ok(())
}
